export const reviewCards = [
  { id: 'core-loop', topic: 'Butano', mission: 2,
    question: 'Where do bn::core::init() and bn::core::update() belong in a minimal game?',
    answer: 'Call init() once before using Butano. Keep update() in the repeating loop so the screen and Butano subsystems advance. Run your input and simulation work each iteration around that frame boundary.',
    url: 'https://gvaliente.github.io/butano/namespacebn_1_1core.html' },
  { id: 'reference', topic: 'C++', mission: 4,
    question: 'void move(int x) { ++x; } leaves the caller unchanged. What changes if x is int&?',
    answer: 'A value parameter is a separate object. An int& parameter names the caller’s int, so incrementing it changes that original object. The referred-to object must remain alive for every use of the reference.',
    url: 'https://eel.is/c++draft/dcl.ref' },
  { id: 'fixed-position', topic: 'C++', mission: 4,
    question: 'Why keep position as bn::fixed when movement is less than one pixel per frame?',
    answer: 'Fixed-point values retain a fractional part using scaled integers. Fractional movement can accumulate over frames before a visible pixel changes. Storing each position update in an int would discard that fractional progress.',
    url: 'https://gvaliente.github.io/butano/classbn_1_1fixed__t.html' },
  { id: 'sprite-lifetime', topic: 'C++', mission: 3,
    question: 'A helper creates a local bn::sprite_ptr, then returns without saving or returning it. Why might the sprite disappear?',
    answer: 'The local handle is destroyed when its scope ends. Butano releases the sprite when its last owning sprite_ptr disappears. Keep a handle in a scope or object that lives as long as the sprite should exist.',
    url: 'https://gvaliente.github.io/butano/classbn_1_1sprite__ptr.html' },
  { id: 'sprite-origin', topic: 'GBA', mission: 3,
    question: 'In Butano’s default centered coordinate convention, where does sprite position (0, 0) appear?',
    answer: 'At the screen center, with the sprite centered there. Positive x moves right and positive y moves down. Keep that convention distinct from top-left image coordinates and any world-space coordinates you introduce.',
    url: 'https://gvaliente.github.io/butano/faq.html' },
  { id: 'input-edge', topic: 'Butano', mission: 5,
    question: 'Which fits continuous walking and which fits toggling pause: a_held() or a_pressed()?',
    answer: 'held() stays true while the button is down, so it suits continuous actions. pressed() reports the transition in the current frame, so it suits one toggle per press. Holding a pause button should not toggle pause every frame.',
    url: 'https://gvaliente.github.io/butano/namespacebn_1_1keypad.html' },
  { id: 'diagonal', topic: 'Game logic', mission: 5,
    question: 'An axis speed is 1. Moving (1, 1) each frame is how much faster than moving (1, 0)?',
    answer: 'Its vector length is √(1² + 1²) = √2, about 1.414. Scale both diagonal components by 1/√2, about 0.707, if your design requires the same total speed in all directions.',
    url: 'https://gvaliente.github.io/butano/classbn_1_1fixed__t.html' },
  { id: 'pause-simulation', topic: 'Game logic', mission: 6,
    question: 'Should a paused game stop calling bn::core::update()? Explain the distinction.',
    answer: 'Keep Butano updating so display and input can continue. Pause the gameplay simulation: skip movement, collisions, and gameplay timers while paused. Continue reading the resume input; otherwise the game cannot respond to it.',
    url: 'https://gvaliente.github.io/butano/namespacebn_1_1core.html' },
  { id: 'aabb', topic: 'Game logic', mission: 7,
    question: 'Two axis-aligned boxes overlap on x but do not overlap on y. Is there a collision?',
    answer: 'No. Rectangle overlap requires overlap on both axes. Decide whether touching edges counts, then use strict or inclusive comparisons consistently. Compare both boxes in the same coordinate space.',
    url: 'https://gvaliente.github.io/butano/classbn_1_1fixed__rect__t.html' },
  { id: 'asset-build', topic: 'Butano', mission: 3,
    question: 'Why can’t a GBA game simply open graphics/player.bmp from your WSL folder?',
    answer: 'Your WSL folder is on the development machine. Butano’s build converts assets into GBA-friendly data, embeds them in the ROM, and generates C++ headers. The BMP and matching JSON are inputs to that build process.',
    url: 'https://gvaliente.github.io/butano/import.html' },
  { id: 'world-camera', topic: 'Game logic', mission: 15,
    question: 'Does moving the camera mean the player’s collision position should change?',
    answer: 'No. Keep gameplay positions in world space. A camera changes their displayed position. For the simple translation model, screen position = world position − camera position. Apply the same camera to related visible world objects.',
    url: 'https://gvaliente.github.io/butano/classbn_1_1camera__ptr.html' },
  { id: 'single-event', topic: 'Game logic', mission: 19,
    question: 'A pickup sound plays every frame while the player overlaps a coin. What state change is missing?',
    answer: 'Represent the transition from available to collected. When overlap first collects an available coin, change its state and trigger score/sound once. Later frames must see that the coin is already collected.',
    url: 'https://gvaliente.github.io/butano/examples.html' },
  { id: 'capacity', topic: 'C++', mission: 22,
    question: 'Does bn::vector<Enemy, 16> grow beyond 16 enemies like a heap-backed std::vector?',
    answer: 'No. Its buffer has fixed capacity: at most 16 elements. Check available capacity and define what spawning does when full. Predictable limits are part of the game’s behavior and memory budget.',
    url: 'https://gvaliente.github.io/butano/classbn_1_1vector.html' },
  { id: 'debug-symbols', topic: 'Debugging', mission: 21,
    question: 'For source-level debugging, why load the matching .elf into GDB alongside the .gba in mGBA?',
    answer: 'The emulator runs the ROM. The ELF can supply GDB with symbols and source mappings when built with debug information. It must match the running build, or names and source locations can mislead you.',
    url: 'https://sourceware.org/gdb/current/onlinedocs/gdb.html/GDB-Files.html' },
  { id: 'step-next', topic: 'Debugging', mission: 21,
    question: 'In GDB, how do next and step differ at a function call?',
    answer: 'next normally advances to another source line in the current frame, executing called functions along the way. step can enter a called function that has source line information. Breakpoints or signals can stop either command sooner.',
    url: 'https://sourceware.org/gdb/current/onlinedocs/gdb.html/Continuing-and-Stepping.html' },
  { id: 'git-index', topic: 'Git', mission: 1,
    question: 'You stage main.cpp, edit it again, and commit normally. Which version is committed?',
    answer: 'The content staged at the time of git add. Later edits stay unstaged unless added again. Use git diff to inspect unstaged edits and git diff --staged to inspect what the next ordinary commit will record.',
    url: 'https://git-scm.com/docs/git-add' },
  { id: 'save-data', topic: 'Butano', mission: 23,
    question: 'Why save simple values and a format version instead of copying a sprite_ptr into SRAM?',
    answer: 'A sprite handle describes a live runtime resource. Save durable game facts such as score or unlocked level, then recreate resources on load. Butano’s typed SRAM copy requires trivially copyable data; validate a version/magic value before trusting a save.',
    url: 'https://gvaliente.github.io/butano/namespacebn_1_1sram.html' },
  { id: 'frame-evidence', topic: 'Debugging', mission: 22,
    question: 'The game feels slow with many enemies. What observation should guide the next change?',
    answer: 'Reproduce the heavy scene, measure CPU usage and missed frames, and compare a smaller scene. Use evidence to locate expensive work before optimizing. Butano exposes last_cpu_usage() and last_missed_frames(); check the result again after a change.',
    url: 'https://gvaliente.github.io/butano/namespacebn_1_1core.html' },
  { id: 'art-silhouette', topic: 'Art', mission: 9,
    question: 'Your tiny character has detailed shading but disappears against the level. What two tests should you try first?',
    answer: 'Preview the sprite at native size, filled with one solid color: can its outer shape communicate its role or pose? Then place it against the actual level and check light/dark contrast. Adjust the large shapes and values before adding small details.',
    url: 'https://steamcdn-a.akamaihd.net/apps/valve/2007/NPAR07_IllustrativeRenderingInTeamFortress2.pdf' },
  { id: 'art-palette-index', topic: 'Art', mission: 10,
    question: 'Why can a sprite pixel become transparent even when its RGB color looks nothing like your chosen background?',
    answer: 'In indexed graphics, pixels store palette indices. For a normal 4bpp GBA sprite, index 0 is transparent regardless of its RGB value; the other 15 indices can be visible. An RGB image using 16 different colors is not automatically a correctly indexed BMP.',
    url: 'https://gvaliente.github.io/butano/import.html' },
  { id: 'art-walk-cycle', topic: 'Art', mission: 11,
    question: 'What do contact, down, passing, and up contribute to a walk? Where might anticipation fit?',
    answer: 'Contact establishes a footfall; down absorbs weight; passing brings the swinging leg past the support leg; up rises toward the next step. Repeat with the legs exchanged. Anticipation prepares a new action, such as leaning before starting. Simplify the poses for a small sprite; keep its anchor consistent.',
    url: 'https://www.animationmentor.com/blog/tutorial-animating-human-walk-cycle/' },
  { id: 'art-tiles-collision', topic: 'Art', mission: 12,
    question: 'A grass tile repeats without a visible seam. Does that tell the game whether the player may walk on it?',
    answer: 'No. Seamlessness is a visual property: neighboring edges should join cleanly. Collision data describes gameplay rules, such as solid or walkable cells. Keep those rules explicit even when they align with the art grid, so changing a decorative tile does not silently change physics.',
    url: 'https://github.com/GValiente/butano/tree/master/examples/map_collision' }
];

export const glossary = [
  { term: 'ROM', definition: 'The game binary loaded by the emulator or cartridge hardware. Your development machine builds it from code and converted assets.', example: 'Untitled-Project.gba is the playable build.' },
  { term: 'ELF', definition: 'An executable/object format that can retain symbols and debug information for tools such as GDB.', example: 'Load the matching game.elf for source-level debugging.' },
  { term: 'Cross-compilation', definition: 'Compiling on one platform for a different target architecture or environment.', example: 'Your Ubuntu machine builds ARM code for the GBA.' },
  { term: 'Game loop', definition: 'The repeating sequence that reads input, updates gameplay, and advances presentation.', example: 'Read the keypad, move the player, check collisions, call core::update().' },
  { term: 'Fixed-point', definition: 'A number represented by an integer with an agreed scale, retaining a limited fractional part.', example: 'bn::fixed x = 0; x += bn::fixed(0.5);' },
  { term: 'RAII', definition: 'C++ resource management that ties ownership to object lifetime. Destruction performs cleanup when the owner’s lifetime ends.', example: 'The final sprite_ptr owner going out of scope releases its sprite.' },
  { term: 'Reference', definition: 'A C++ name bound to another object. A reference parameter can access the caller’s object directly.', example: 'void heal(int& health) { ++health; }' },
  { term: 'Sprite', definition: 'A separately positioned graphical object, often used for characters, effects, or interface elements.', example: 'bn::sprite_items::player.create_sprite(0, 0)' },
  { term: 'Tile', definition: 'A small reusable block of graphics. GBA sprite and tiled background graphics are assembled from 8 × 8 pixel tiles.', example: 'A tiled floor reuses a few patterns across a map.' },
  { term: 'Palette', definition: 'A table mapping indexed pixel values to colors. Palette index zero has a transparency role in normal sprite graphics.', example: 'A 4bpp sprite indexes a palette of up to 16 colors.' },
  { term: 'AABB', definition: 'An axis-aligned bounding box. A simple collision shape whose edges stay parallel to the coordinate axes.', example: 'Two rectangles overlap only when their horizontal and vertical ranges both overlap.' },
  { term: 'State machine', definition: 'A model with a defined set of states and rules for transitioning between them.', example: 'An enemy changes from patrol to chase when the player enters its detection range.' },
  { term: 'Camera', definition: 'A viewing offset that changes how world objects appear on screen while preserving their gameplay positions.', example: 'A player at world x = 200 and camera x = 150 appears at centered screen x = 50.' },
  { term: 'Breakpoint', definition: 'A debugger instruction to stop execution at a chosen location or condition so you can inspect program state.', example: 'break update_player pauses when that function is reached.' },
  { term: 'Staging area', definition: 'Git’s prepared snapshot for the next commit, also called the index.', example: 'git add src/main.cpp updates the staged content of that file.' },
  { term: 'SRAM', definition: 'Save storage accessible through Butano’s SRAM functions. Store stable data and validate it when loading.', example: 'Save a version number, high score, and level unlock values.' },
  { term: 'Frame budget', definition: 'The time available to finish work for one displayed frame. Excess work can cause missed refreshes.', example: 'Measure a crowded scene before deciding which system needs optimization.' },
  { term: 'Transfer', definition: 'Applying a learned idea in a new situation without repeating an exact recipe.', example: 'After coding coins, design a pressure plate using the same event and collision ideas.' },
  { term: 'Sprite sheet', definition: 'One image containing several sprite frames in a regular arrangement. Export dimensions and frame order must match the importer’s expectations.', example: 'Draw four original 16 × 16 walk frames; export a 64 × 16 row and specify frame dimensions in the Butano JSON.' },
  { term: 'Onion skin', definition: 'An editor overlay showing neighboring animation frames as drawing references. It helps compare a new pose with the frames around it.', example: 'Ghost the previous and next frame while keeping your character’s feet aligned to the same ground guide.' },
  { term: 'Silhouette', definition: 'An object’s outer shape viewed as a flat filled form. A clear silhouette can make a tiny character’s identity and pose easier to read.', example: 'Fill your 16 × 16 adventurer with one dark color; separate the hat, arm, and tool enough to recognize them.' }
];

